Object.assign(window.CODELAB_OFFLINE_PACKS,{"topic-beforeandafterpuzzle":{"key":"topic-beforeandafterpuzzle","number":null,"title":"Before and After Puzzle","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Before and After Puzzle.py","code":"class Solution:\n    def beforeAndAfterPuzzles(self, phrases: List[str]) -> List[str]:\n        hashMap, result = defaultdict(set), set()\n        for i, phrase in enumerate(phrases):\n            parts = phrase.split(' ', 1)\n            hashMap[parts[0]].add((phrase, i))\n        for i, phrase in enumerate(phrases):\n            parts = phrase.rsplit(' ', 1)\n            if parts[-1] in hashMap:\n                for p, j in hashMap[parts[-1]]:\n                    if i != j:\n                        result.add(' '.join(parts[:-1] + p.split()))\n        return sorted(result)","hash":"a9fd1bf57c41fb59bcba2dbe6b087a4a2ecd65cab8ab5732a2255d5c3f0b956d","origins":[{"source":"solutions","path":"Before and After Puzzle.py"}]}],"sources":["solutions"]},"topic-bestpokerhand":{"key":"topic-bestpokerhand","number":null,"title":"Best Poker Hand","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Best Poker Hand.py","code":"class Solution:\n    def bestHand(self, ranks: List[int], suits: List[str]) -> str:\n        availableSuitTypes, availableRankFreq = len(set(suits)), Counter(ranks)\n        if availableSuitTypes == 1:\n            return \"Flush\"\n        elif max(availableRankFreq.values()) >= 3:\n            return \"Three of a Kind\"\n        elif max(availableRankFreq.values()) == 2:\n            return \"Pair\"\n        else:\n            return \"High Card\"","hash":"55c085bd5c29d712672f3b6736b0e9f146ad32928cf8b7e38ff5374024333e9f","origins":[{"source":"solutions","path":"Best Poker Hand.py"}]}],"sources":["solutions"]},"topic-bestsightseeingpair":{"key":"topic-bestsightseeingpair","number":null,"title":"Best Sightseeing Pair","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Best Sightseeing Pair.py","code":"class Solution:\n    def maxScoreSightseeingPair(self, A: List[int]) -> int:\n        getScore = lambda i, j : (A[i] + A[j] + i - j)\n        a, b = 0, 1\n        dp = [A[0], getScore(0, 1)] + [0 for _ in range(2, len(A))]\n        maxScore = max(dp[0], dp[1])\n        for i in range(2, len(A)):\n            scorea, scoreb = getScore(a, i), getScore(b, i)\n            if scorea > scoreb:\n                dp[i] = scorea\n                b = i\n            else:\n                dp[i] = scoreb\n                a, b = b, i\n            maxScore = max(maxScore, dp[i])\n        return maxScore","hash":"f98920eabe798b418d88a15eb75074733d416dc99d710fa66b2964c061638d9b","origins":[{"source":"solutions","path":"Best Sightseeing Pair.py"}]}],"sources":["solutions"]},"topic-bestteamwithnoconflicts":{"key":"topic-bestteamwithnoconflicts","number":null,"title":"Best Team With No Conflicts","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Best Team With No Conflicts.py","code":"class Solution:\n    def bestTeamScore(self, scores: List[int], ages: List[int]) -> int:\n        n, zippedList, bestScore = len(scores), sorted(zip(ages, scores)), scores[0]\n        dp = [c[1] for c in zippedList]\n        for i in range(1, n):\n            for j in range(i):\n                if zippedList[i][1] >= zippedList[j][1]:\n                    dp[i] = max(dp[i], dp[j] + zippedList[i][1])\n                bestScore = max(bestScore, dp[i])\n        return bestScore","hash":"db306209d054d5e2d218daa57a5ea971550c1fc08b893c16c49a11ab35b3f3ef","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-01 Leetcoding Challenge/Best Team With No Conflicts.py"}]},{"language":"python","name":"Best Team With No Conflicts.py","code":"class Solution:\n    def bestTeamScore(self, scores: List[int], ages: List[int]) -> int:\n        n, zippedList, bestScore = len(scores), sorted(zip(ages, scores)), 1\n        dp = [c[1] for c in zippedList]\n        for i in range(1, n):\n            for j in range(i):\n                if zippedList[i][1] >= zippedList[j][1]:\n                    dp[i] = max(dp[i], dp[j] + zippedList[i][1])\n                bestScore = max(bestScore, dp[i])\n        return bestScore","hash":"4d8ccf36abab3d342a3d6c02d2fb0acbfbc6f98e1beac2b50a4f69fcaf54b569","origins":[{"source":"solutions","path":"Weekly Contests/Weekly Contest 211/Best Team With No Conflicts.py"}]}],"sources":["solutions"]},"topic-besttimetobuyandsellstock":{"key":"topic-besttimetobuyandsellstock","number":null,"title":"Best Time to Buy and Sell Stock","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Best Time to Buy and Sell Stock.py","code":"class Solution:\n    def maxProfit(self, prices: List[int]) -> int:\n        minPrice = float('inf')\n        maxProfit = 0\n        for price in prices:\n            if price < minPrice:\n                minPrice = price\n            elif price - minPrice > maxProfit:\n                maxProfit = price - minPrice\n        return maxProfit","hash":"11bb80952315cbf0ff46b4415ba2c0ac6ebd14ccd671d7abe35c458099824a21","origins":[{"source":"solutions","path":"Google Interview Questions/Best Time to Buy and Sell Stock.py"}]},{"language":"python","name":"Best Time to Buy and Sell Stock.py","code":"class Solution:\n    def maxProfit(self, prices: List[int]) -> int:\n        maxProfit, minCost = 0, float('inf')\n        for price in prices:\n            minCost = min(minCost, price)\n            maxProfit = max(maxProfit, price - minCost)\n        return maxProfit","hash":"59b0c5b87a44e82502dd8d738faaafe52bf645695a5da72ff31eab59abce7d0d","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-09 Leetcoding Challenge/Best Time to Buy and Sell Stock.py"},{"source":"solutions","path":"LeetCoding Challenges/2022/2022-02 Leetcoding Challenge/Best Time to Buy and Sell Stock.py"}]},{"language":"python","name":"Best Time to Buy and Sell Stock.py","code":"class Solution:\n    def maxProfit(self, prices: List[int]) -> int:\n        buy, result = 100000, 0\n        for price in prices:\n            if price >= buy:\n                result = max(result, price - buy)\n            buy = min(price, buy)\n        return result","hash":"1a14faeba340c055665e549189a5b374c0865eb2d920100203a744fae4634c64","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-02 Leetcoding Challenge/Best Time to Buy and Sell Stock.py"}]}],"sources":["solutions"]},"topic-besttimetobuyandsellstockii":{"key":"topic-besttimetobuyandsellstockii","number":null,"title":"Best Time to Buy and Sell Stock II","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Best Time to Buy and Sell Stock II.py","code":"class Solution:\n    def maxProfit(self, prices: List[int]) -> int:\n        maximumProfit = 0\n        for i in range(1, len(prices)):\n            if prices[i] > prices[i - 1]:\n                maximumProfit += (prices[i] - prices[i - 1])\n        return maximumProfit","hash":"863b5904037e10d20cce753ea2ccdc1b5655079abf43ba406e4c24c8d1bd78f5","origins":[{"source":"solutions","path":"Best Time to Buy and Sell Stock II.py"}]}],"sources":["solutions"]},"topic-besttimetobuyandsellstockwithcooldown":{"key":"topic-besttimetobuyandsellstockwithcooldown","number":null,"title":"Best Time to Buy and Sell Stock with Cooldown","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Best Time to Buy and Sell Stock with Cooldown.py","code":"class Solution:\n    def maxProfit(self, prices: List[int]) -> int:\n        sold, held, reset = float('-inf'), float('-inf'), 0\n        for price in prices:\n            sold, held, reset = held + price, max(held, reset - price), max(reset, sold)\n        return max(sold, reset)","hash":"182bd6c726d43fed82f0249894aaba123665352cce49ac0c7ad6bf383e10a594","origins":[{"source":"solutions","path":"Best Time to Buy and Sell Stock with Cooldown.py"},{"source":"solutions","path":"LeetCoding Challenges/2022/2022-12 Leetcoding Challenge/Best Time to Buy and Sell Stock with Cooldown.py"}]}],"sources":["solutions"]},"topic-binarynumberwithalternatingbits":{"key":"topic-binarynumberwithalternatingbits","number":null,"title":"Binary Number with Alternating Bits","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Binary Number with Alternating Bits.py","code":"class Solution:\n    def hasAlternatingBits(self, n: int) -> bool:\n        def checkBit(num, i):\n            return (num >> i) & 1 == 1\n        msb = 32\n        for i in range(32, -1, -1):\n            if checkBit(n, i):\n                msb = i\n                break\n        for i in range(msb, 0, -1):\n            if checkBit(n, i) ^ checkBit(n, i - 1) == 0:\n                return False\n        return True","hash":"023a27e702b931f23f619861f83b2d387e4b75b8e08feff5d67cc8fd5dbaa93b","origins":[{"source":"solutions","path":"Binary Number with Alternating Bits.py"}]}],"sources":["solutions"]},"topic-binarysearch":{"key":"topic-binarysearch","number":null,"title":"Binary Search","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Binary Search.py","code":"class Solution:\n    def search(self, nums: List[int], target: int) -> int:\n        left, right = 0, len(nums) - 1\n        while left <= right:\n            mid = left + (right - left) // 2\n            if nums[mid] == target:\n                return mid\n            elif nums[mid] < target:\n                left = mid + 1\n            else:\n                right = mid - 1\n        return -1","hash":"127cabae32e05939ba051e452420c1d63e76c473045aae26768d6259bae97b3c","origins":[{"source":"solutions","path":"Binary Search/Binary Search.py"}]},{"language":"python","name":"Binary Search.py","code":"class Solution:\n    def search(self, nums: List[int], target: int) -> int:\n        low, high = 0, len(nums)\n        while low < high:\n            mid = low + (high - low) // 2\n            if nums[mid] == target:\n                return mid\n            elif nums[mid] < target:\n                low = mid + 1\n            else:\n                high = mid\n        return -1","hash":"a12623ba522dfe245b536461f0a3e655465a4b2b60def5108cf7fa2305a70224","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-10 Leetcoding Challenge/Binary Search.py"},{"source":"solutions","path":"LeetCoding Challenges/2022/2022-03 Leetcoding Challenge/Binary Search.py"}]},{"language":"python","name":"Binary Search.py","code":"class Solution:\n    def search(self, nums: List[int], target: int) -> int:\n        low, high = 0, len(nums)\n        while low < high:\n            mid = low + ((high - low) >> 1)\n            if nums[mid] == target:\n                return mid\n            elif nums[mid] < target:\n                low = mid + 1\n            else:\n                high = mid\n        return -1","hash":"37086aa6a80cb06725c1b2722fed6ad3311443ccf760114de90fd28c9327b70a","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-04 Leetcoding Challenge/Binary Search.py"}]}],"sources":["solutions"]},"algorithm-binary-search":{"key":"algorithm-binary-search","number":null,"title":"binary search","difficulty":"Unknown","tags":["Algorithm Reference"],"documents":[],"sources":["algorithms"],"solutions":[{"language":"python","name":"binary_search.py","code":"#!/usr/bin/env python3\n\n\"\"\"\nPure Python implementations of binary search algorithms\n\nFor doctests run the following command:\npython3 -m doctest -v binary_search.py\n\nFor manual testing run:\npython3 binary_search.py\n\"\"\"\n\nimport bisect\nfrom itertools import pairwise\n\n\ndef bisect_left(\n    sorted_collection: list[int], item: int, lo: int = 0, hi: int = -1\n) -> int:\n    \"\"\"\n    Locates the first element in a sorted array that is larger or equal to a given\n    value.\n\n    It has the same interface as\n    https://docs.python.org/3/library/bisect.html#bisect.bisect_left .\n\n    :param sorted_collection: some ascending sorted collection with comparable items\n    :param item: item to bisect\n    :param lo: lowest index to consider (as in sorted_collection[lo:hi])\n    :param hi: past the highest index to consider (as in sorted_collection[lo:hi])\n    :return: index i such that all values in sorted_collection[lo:i] are < item and all\n        values in sorted_collection[i:hi] are >= item.\n\n    Examples:\n    >>> bisect_left([0, 5, 7, 10, 15], 0)\n    0\n    >>> bisect_left([0, 5, 7, 10, 15], 6)\n    2\n    >>> bisect_left([0, 5, 7, 10, 15], 20)\n    5\n    >>> bisect_left([0, 5, 7, 10, 15], 15, 1, 3)\n    3\n    >>> bisect_left([0, 5, 7, 10, 15], 6, 2)\n    2\n    >>> bisect_left([], 2)\n    0\n    >>> bisect_left([2, 2, 2], 2)\n    0\n    >>> bisect_left([1, 2, 2, 2, 4], 2)\n    1\n    \"\"\"\n    if hi < 0:\n        hi = len(sorted_collection)\n\n    while lo < hi:\n        mid = lo + (hi - lo) // 2\n        if sorted_collection[mid] < item:\n            lo = mid + 1\n        else:\n            hi = mid\n\n    return lo\n\n\ndef bisect_right(\n    sorted_collection: list[int], item: int, lo: int = 0, hi: int = -1\n) -> int:\n    \"\"\"\n    Locates the first element in a sorted array that is larger than a given value.\n\n    It has the same interface as\n    https://docs.python.org/3/library/bisect.html#bisect.bisect_right .\n\n    :param sorted_collection: some ascending sorted collection with comparable items\n    :param item: item to bisect\n    :param lo: lowest index to consider (as in sorted_collection[lo:hi])\n    :param hi: past the highest index to consider (as in sorted_collection[lo:hi])\n    :return: index i such that all values in sorted_collection[lo:i] are <= item and\n        all values in sorted_collection[i:hi] are > item.\n\n    Examples:\n    >>> bisect_right([0, 5, 7, 10, 15], 0)\n    1\n    >>> bisect_right([0, 5, 7, 10, 15], 15)\n    5\n    >>> bisect_right([0, 5, 7, 10, 15], 6)\n    2\n    >>> bisect_right([0, 5, 7, 10, 15], 15, 1, 3)\n    3\n    >>> bisect_right([0, 5, 7, 10, 15], 6, 2)\n    2\n    >>> bisect_right([], 2)\n    0\n    >>> bisect_right([2, 2, 2], 2)\n    3\n    >>> bisect_right([1, 2, 2, 2, 4], 2)\n    4\n    \"\"\"\n    if hi < 0:\n        hi = len(sorted_collection)\n\n    while lo < hi:\n        mid = lo + (hi - lo) // 2\n        if sorted_collection[mid] <= item:\n            lo = mid + 1\n        else:\n            hi = mid\n\n    return lo\n\n\ndef insort_left(\n    sorted_collection: list[int], item: int, lo: int = 0, hi: int = -1\n) -> None:\n    \"\"\"\n    Inserts a given value into a sorted array before other values with the same value.\n\n    It has the same interface as\n    https://docs.python.org/3/library/bisect.html#bisect.insort_left .\n\n    :param sorted_collection: some ascending sorted collection with comparable items\n    :param item: item to insert\n    :param lo: lowest index to consider (as in sorted_collection[lo:hi])\n    :param hi: past the highest index to consider (as in sorted_collection[lo:hi])\n\n    Examples:\n    >>> sorted_collection = [0, 5, 7, 10, 15]\n    >>> insort_left(sorted_collection, 6)\n    >>> sorted_collection\n    [0, 5, 6, 7, 10, 15]\n    >>> sorted_collection = [(0, 0), (5, 5), (7, 7), (10, 10), (15, 15)]\n    >>> item = (5, 5)\n    >>> insort_left(sorted_collection, item)\n    >>> sorted_collection\n    [(0, 0), (5, 5), (5, 5), (7, 7), (10, 10), (15, 15)]\n    >>> item is sorted_collection[1]\n    True\n    >>> item is sorted_collection[2]\n    False\n    >>> sorted_collection = [0, 5, 7, 10, 15]\n    >>> insort_left(sorted_collection, 20)\n    >>> sorted_collection\n    [0, 5, 7, 10, 15, 20]\n    >>> sorted_collection = [0, 5, 7, 10, 15]\n    >>> insort_left(sorted_collection, 15, 1, 3)\n    >>> sorted_collection\n    [0, 5, 7, 15, 10, 15]\n    \"\"\"\n    sorted_collection.insert(bisect_left(sorted_collection, item, lo, hi), item)\n\n\ndef insort_right(\n    sorted_collection: list[int], item: int, lo: int = 0, hi: int = -1\n) -> None:\n    \"\"\"\n    Inserts a given value into a sorted array after other values with the same value.\n\n    It has the same interface as\n    https://docs.python.org/3/library/bisect.html#bisect.insort_right .\n\n    :param sorted_collection: some ascending sorted collection with comparable items\n    :param item: item to insert\n    :param lo: lowest index to consider (as in sorted_collection[lo:hi])\n    :param hi: past the highest index to consider (as in sorted_collection[lo:hi])\n\n    Examples:\n    >>> sorted_collection = [0, 5, 7, 10, 15]\n    >>> insort_right(sorted_collection, 6)\n    >>> sorted_collection\n    [0, 5, 6, 7, 10, 15]\n    >>> sorted_collection = [(0, 0), (5, 5), (7, 7), (10, 10), (15, 15)]\n    >>> item = (5, 5)\n    >>> insort_right(sorted_collection, item)\n    >>> sorted_collection\n    [(0, 0), (5, 5), (5, 5), (7, 7), (10, 10), (15, 15)]\n    >>> item is sorted_collection[1]\n    False\n    >>> item is sorted_collection[2]\n    True\n    >>> sorted_collection = [0, 5, 7, 10, 15]\n    >>> insort_right(sorted_collection, 20)\n    >>> sorted_collection\n    [0, 5, 7, 10, 15, 20]\n    >>> sorted_collection = [0, 5, 7, 10, 15]\n    >>> insort_right(sorted_collection, 15, 1, 3)\n    >>> sorted_collection\n    [0, 5, 7, 15, 10, 15]\n    \"\"\"\n    sorted_collection.insert(bisect_right(sorted_collection, item, lo, hi), item)\n\n\ndef binary_search(sorted_collection: list[int], item: int) -> int:\n    \"\"\"Pure implementation of a binary search algorithm in Python\n\n    Be careful collection must be ascending sorted otherwise, the result will be\n    unpredictable\n\n    :param sorted_collection: some ascending sorted collection with comparable items\n    :param item: item value to search\n    :return: index of the found item or -1 if the item is not found.\n             If there are multiple occurrences of the item, returns the index\n             of the leftmost occurrence.\n\n    Examples:\n    >>> binary_search([0, 5, 7, 10, 15], 0)\n    0\n    >>> binary_search([0, 5, 7, 10, 15], 15)\n    4\n    >>> binary_search([0, 5, 7, 10, 15], 5)\n    1\n    >>> binary_search([0, 5, 7, 10, 15], 6)\n    -1\n    >>> binary_search([1, 2, 4, 4, 4, 6, 7], 4)\n    2\n    >>> binary_search([0, 5, 7, 10, 10, 10], 10)\n    3\n    \"\"\"\n    if any(a > b for a, b in pairwise(sorted_collection)):\n        raise ValueError(\"sorted_collection must be sorted in ascending order\")\n    left = 0\n    right = len(sorted_collection) - 1\n    result = -1\n\n    while left <= right:\n        midpoint = left + (right - left) // 2\n        current_item = sorted_collection[midpoint]\n        if current_item == item:\n            result = (\n                midpoint  # Found the item, but continue to find leftmost occurrence\n            )\n            right = midpoint - 1  # Look for more occurrences on the left\n        elif item < current_item:\n            right = midpoint - 1\n        else:\n            left = midpoint + 1\n    return result\n\n\ndef binary_search_std_lib(sorted_collection: list[int], item: int) -> int:\n    \"\"\"Pure implementation of a binary search algorithm in Python using stdlib\n\n    Be careful collection must be ascending sorted otherwise, the result will be\n    unpredictable\n\n    :param sorted_collection: some ascending sorted collection with comparable items\n    :param item: item value to search\n    :return: index of the found item or -1 if the item is not found\n\n    Examples:\n    >>> binary_search_std_lib([0, 5, 7, 10, 15], 0)\n    0\n    >>> binary_search_std_lib([0, 5, 7, 10, 15], 15)\n    4\n    >>> binary_search_std_lib([0, 5, 7, 10, 15], 5)\n    1\n    >>> binary_search_std_lib([0, 5, 7, 10, 15], 6)\n    -1\n    \"\"\"\n    if list(sorted_collection) != sorted(sorted_collection):\n        raise ValueError(\"sorted_collection must be sorted in ascending order\")\n    index = bisect.bisect_left(sorted_collection, item)\n    if index != len(sorted_collection) and sorted_collection[index] == item:\n        return index\n    return -1\n\n\ndef binary_search_with_duplicates(sorted_collection: list[int], item: int) -> list[int]:\n    \"\"\"Pure implementation of a binary search algorithm in Python that supports\n    duplicates.\n\n    Resources used:\n    https://stackoverflow.com/questions/13197552/using-binary-search-with-sorted-array-with-duplicates\n\n    The collection must be sorted in ascending order; otherwise the result will be\n    unpredictable. If the target appears multiple times, this function returns a\n    list of all indexes where the target occurs. If the target is not found,\n    this function returns an empty list.\n\n    :param sorted_collection: some ascending sorted collection with comparable items\n    :param item: item value to search for\n    :return: a list of indexes where the item is found (empty list if not found)\n\n    Examples:\n    >>> binary_search_with_duplicates([0, 5, 7, 10, 15], 0)\n    [0]\n    >>> binary_search_with_duplicates([0, 5, 7, 10, 15], 15)\n    [4]\n    >>> binary_search_with_duplicates([1, 2, 2, 2, 3], 2)\n    [1, 2, 3]\n    >>> binary_search_with_duplicates([1, 2, 2, 2, 3], 4)\n    []\n    \"\"\"\n    if list(sorted_collection) != sorted(sorted_collection):\n        raise ValueError(\"sorted_collection must be sorted in ascending order\")\n\n    def lower_bound(sorted_collection: list[int], item: int) -> int:\n        \"\"\"\n        Returns the index of the first element greater than or equal to the item.\n\n        :param sorted_collection: The sorted list to search.\n        :param item: The item to find the lower bound for.\n        :return: The index where the item can be inserted while maintaining order.\n        \"\"\"\n        left = 0\n        right = len(sorted_collection)\n        while left < right:\n            midpoint = left + (right - left) // 2\n            current_item = sorted_collection[midpoint]\n            if current_item < item:\n                left = midpoint + 1\n            else:\n                right = midpoint\n        return left\n\n    def upper_bound(sorted_collection: list[int], item: int) -> int:\n        \"\"\"\n        Returns the index of the first element strictly greater than the item.\n\n        :param sorted_collection: The sorted list to search.\n        :param item: The item to find the upper bound for.\n        :return: The index where the item can be inserted after all existing instances.\n        \"\"\"\n        left = 0\n        right = len(sorted_collection)\n        while left < right:\n            midpoint = left + (right - left) // 2\n            current_item = sorted_collection[midpoint]\n            if current_item <= item:\n                left = midpoint + 1\n            else:\n                right = midpoint\n        return left\n\n    left = lower_bound(sorted_collection, item)\n    right = upper_bound(sorted_collection, item)\n\n    if left == len(sorted_collection) or sorted_collection[left] != item:\n        return []\n    return list(range(left, right))\n\n\ndef binary_search_by_recursion(\n    sorted_collection: list[int], item: int, left: int = 0, right: int = -1\n) -> int:\n    \"\"\"Pure implementation of a binary search algorithm in Python by recursion\n\n    Be careful collection must be ascending sorted otherwise, the result will be\n    unpredictable\n    First recursion should be started with left=0 and right=(len(sorted_collection)-1)\n\n    :param sorted_collection: some ascending sorted collection with comparable items\n    :param item: item value to search\n    :return: index of the found item or -1 if the item is not found.\n             If there are multiple occurrences of the item, returns the index\n             of the leftmost occurrence.\n\n    Examples:\n    >>> binary_search_by_recursion([0, 5, 7, 10, 15], 0, 0, 4)\n    0\n    >>> binary_search_by_recursion([0, 5, 7, 10, 15], 15, 0, 4)\n    4\n    >>> binary_search_by_recursion([0, 5, 7, 10, 15], 5, 0, 4)\n    1\n    >>> binary_search_by_recursion([0, 5, 7, 10, 15], 6, 0, 4)\n    -1\n    >>> binary_search_by_recursion([1, 2, 4, 4, 4, 6, 7], 4, 0, 6)\n    2\n    >>> binary_search_by_recursion([0, 5, 7, 10, 10, 10], 10, 0, 5)\n    3\n    \"\"\"\n    if right < 0:\n        right = len(sorted_collection) - 1\n    if list(sorted_collection) != sorted(sorted_collection):\n        raise ValueError(\"sorted_collection must be sorted in ascending order\")\n\n    # Helper function for the binary search\n    def _binary_search_recursive(left_idx: int, right_idx: int) -> int:\n        if right_idx < left_idx:\n            return -1\n\n        midpoint = left_idx + (right_idx - left_idx) // 2\n        current_item = sorted_collection[midpoint]\n\n        if current_item == item:\n            # Found the item, now find the leftmost occurrence\n            # First, recursively find any occurrence to the left\n            leftmost = _binary_search_recursive(left_idx, midpoint - 1)\n            return leftmost if leftmost != -1 else midpoint\n        elif item < current_item:\n            return _binary_search_recursive(left_idx, midpoint - 1)\n        else:\n            return _binary_search_recursive(midpoint + 1, right_idx)\n\n    return _binary_search_recursive(left, right)\n\n\ndef exponential_search(sorted_collection: list[int], item: int) -> int:\n    \"\"\"Pure implementation of an exponential search algorithm in Python\n    Resources used:\n    https://en.wikipedia.org/wiki/Exponential_search\n\n    Be careful collection must be ascending sorted otherwise, result will be\n    unpredictable\n\n    :param sorted_collection: some ascending sorted collection with comparable items\n    :param item: item value to search\n    :return: index of the found item or -1 if the item is not found\n\n    the order of this algorithm is O(lg I) where I is index position of item if exist\n\n    Examples:\n    >>> exponential_search([0, 5, 7, 10, 15], 0)\n    0\n    >>> exponential_search([0, 5, 7, 10, 15], 15)\n    4\n    >>> exponential_search([0, 5, 7, 10, 15], 5)\n    1\n    >>> exponential_search([0, 5, 7, 10, 15], 6)\n    -1\n    \"\"\"\n    if list(sorted_collection) != sorted(sorted_collection):\n        raise ValueError(\"sorted_collection must be sorted in ascending order\")\n    bound = 1\n    while bound < len(sorted_collection) and sorted_collection[bound] < item:\n        bound *= 2\n    left = bound // 2\n    right = min(bound, len(sorted_collection) - 1)\n    last_result = binary_search_by_recursion(\n        sorted_collection=sorted_collection, item=item, left=left, right=right\n    )\n    if last_result is None:\n        return -1\n    return last_result\n\n\nsearches = (  # Fastest to slowest...\n    binary_search_std_lib,\n    binary_search,\n    exponential_search,\n    binary_search_by_recursion,\n)\n\n\nif __name__ == \"__main__\":\n    import doctest\n    import timeit\n\n    doctest.testmod()\n    for search in searches:\n        name = f\"{search.__name__:>26}\"\n        print(f\"{name}: {search([0, 5, 7, 10, 15], 10) = }\")  # type: ignore[operator]\n\n    print(\"\\nBenchmarks...\")\n    setup = \"collection = range(1000)\"\n    for search in searches:\n        name = search.__name__\n        print(\n            f\"{name:>26}:\",\n            timeit.timeit(\n                f\"{name}(collection, 500)\", setup=setup, number=5_000, globals=globals()\n            ),\n        )\n\n    user_input = input(\"\\nEnter numbers separated by comma: \").strip()\n    collection = sorted(int(item) for item in user_input.split(\",\"))\n    target = int(input(\"Enter a single number to be found in the list: \"))\n    result = binary_search(sorted_collection=collection, item=target)\n    if result == -1:\n        print(f\"{target} was not found in {collection}.\")\n    else:\n        print(f\"{target} was found at position {result} of {collection}.\")\n","hash":"9891d9031e518a961f7dcde4686f7f3ceda0e4d77557b6eb5676753caa0327d5","origins":[{"source":"algorithms","path":"searches/binary_search.py","url":"https://github.com/TheAlgorithms/Python/blob/25c712f2692449e91a57748d328ef34fccf25654/searches/binary_search.py","commit":"25c712f2692449e91a57748d328ef34fccf25654"}]}]},"topic-binarysearchtreeiterator":{"key":"topic-binarysearchtreeiterator","number":null,"title":"Binary Search Tree Iterator","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Binary Search Tree Iterator.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass BSTIterator:\n\n    def __init__(self, root: TreeNode):\n        self._stack = deque()\n        self._processInorderLeftSubtree(root)\n        \n    def _processInorderLeftSubtree(self, node):\n        while node:\n            self._stack.append(node)\n            node = node.left\n\n    def next(self) -> int:\n        \"\"\"\n        @return the next smallest number\n        \"\"\"\n        nextNode = self._stack.pop()\n        if nextNode.right:\n            self._processInorderLeftSubtree(nextNode.right)\n        return nextNode.val\n\n    def hasNext(self) -> bool:\n        \"\"\"\n        @return whether we have a next smallest number\n        \"\"\"\n        return len(self._stack) > 0\n\n\n# Your BSTIterator object will be instantiated and called as such:\n# obj = BSTIterator(root)\n# param_1 = obj.next()\n# param_2 = obj.hasNext()","hash":"e6f24a273261e4e1ef47b20335149198622793d4deae0a0b4eb4fba60587a44b","origins":[{"source":"solutions","path":"Binary Search Tree/Binary Search Tree Iterator.py"},{"source":"solutions","path":"LeetCoding Challenges/2020/2020-12 Leetcoding Challenge/Binary Search Tree Iterator.py"},{"source":"solutions","path":"LeetCoding Challenges/2022/2022-04 Leetcoding Challenge/Binary Search Tree Iterator.py"}]}],"sources":["solutions"]},"topic-binarysearchtreetogreatersumtree":{"key":"topic-binarysearchtreetogreatersumtree","number":null,"title":"Binary Search Tree to Greater Sum Tree","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Binary Search Tree to Greater Sum Tree.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def bstToGst(self, root: TreeNode) -> TreeNode:\n        currentSum = 0\n        def dfs(node):\n            nonlocal currentSum\n            if node:\n                dfs(node.right)\n                currentSum += node.val\n                node.val = currentSum\n                dfs(node.left)\n        dfs(root)\n        return root","hash":"89fbabab20904e6c700ad06bff6f33c0a79a6ea79fc04811b57ce74b0d06ac38","origins":[{"source":"solutions","path":"Binary Search Tree to Greater Sum Tree.py"}]}],"sources":["solutions"]},"topic-binarytreeinordertraversaliterative":{"key":"topic-binarytreeinordertraversaliterative","number":null,"title":"Binary Tree Inorder Traversal Iterative","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Binary Tree Inorder Traversal - Iterative.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def inorderTraversal(self, root: TreeNode) -> List[int]:\n        stack, result, node = deque(), [], root\n        while stack or node is not None:\n            while node:\n                stack.append(node)\n                node = node.left\n            node = stack.pop()\n            result.append(node.val)\n            node = node.right\n        return result","hash":"94558ee7e2e898eb44bc5c48ac5877f515da8840a4a625a27fe58686faf09c1a","origins":[{"source":"solutions","path":"Binary Tree/Binary Tree Inorder Traversal - Iterative.py"}]},{"language":"python","name":"Binary Tree Inorder Traversal - Iterative.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def inorderTraversal(self, root: TreeNode) -> List[int]:\n        stack = deque()\n        result = []\n        currentNode = root\n        while currentNode is not None or len(stack) != 0:\n            while currentNode is not None:\n                stack.append(currentNode)\n                currentNode = currentNode.left\n            currentNode = stack.pop()\n            result.append(currentNode.val)\n            currentNode = currentNode.right\n        return result","hash":"1c2dfd71260eb384bba48d2d69048b944b3127a32fcbf832f991875b91df4e34","origins":[{"source":"solutions","path":"Stacks and Queues/Binary Tree Inorder Traversal - Iterative.py"}]}],"sources":["solutions"]},"topic-binarytreeinordertraversalmorristraversal":{"key":"topic-binarytreeinordertraversalmorristraversal","number":null,"title":"Binary Tree Inorder Traversal Morris Traversal","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Binary Tree Inorder Traversal - Morris Traversal.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def inorderTraversal(self, root: TreeNode) -> List[int]:\n        result, node = [], root\n        while node:\n            if node.left is None:\n                result.append(node.val)\n                node = node.right\n            else:\n                predecessor = node.left\n                while predecessor.right:\n                    predecessor = predecessor.right\n                predecessor.right = node\n                temp = node\n                node = node.left\n                temp.left = None\n        return result","hash":"01a22c4391bfa892ec60f244d90fddb64be211333aa04ec592f4367cb47095c8","origins":[{"source":"solutions","path":"Binary Tree/Binary Tree Inorder Traversal - Morris Traversal.py"}]}],"sources":["solutions"]},"topic-binarytreeinordertraversalrecursive":{"key":"topic-binarytreeinordertraversalrecursive","number":null,"title":"Binary Tree Inorder Traversal Recursive","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Binary Tree Inorder Traversal - Recursive.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def inorderTraversal(self, root: TreeNode) -> List[int]:\n        return self.inorderTraversal(root.left) + [root.val] + self.inorderTraversal(root.right) if root else []","hash":"f7d3cf31205c4b74ec968dfa4f84354bebcec820c5add81bba4713fb79c46639","origins":[{"source":"solutions","path":"Binary Tree/Binary Tree Inorder Traversal - Recursive.py"},{"source":"solutions","path":"Stacks and Queues/Binary Tree Inorder Traversal - Recursive.py"}]}],"sources":["solutions"]},"topic-binarytreelevelordertraversalii":{"key":"topic-binarytreelevelordertraversalii","number":null,"title":"Binary Tree Level Order Traversal II","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Binary Tree Level Order Traversal II.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def levelOrderBottom(self, root: Optional[TreeNode]) -> List[List[int]]:\n        if root is None:\n            return []\n        queue = deque([root])\n        result = []\n        while queue:\n            currentLevelQueue = queue\n            currentLevelValues = []\n            queue = deque([])\n            while currentLevelQueue:\n                node = currentLevelQueue.popleft()\n                currentLevelValues.append(node.val)\n                if node.left:\n                    queue.append(node.left)\n                if node.right:\n                    queue.append(node.right)\n            result.append(currentLevelValues)\n        return result[::-1]","hash":"d586c0acf763556b2473716e9f7e665f0b9faf00a36fc65d15db39704f949c21","origins":[{"source":"solutions","path":"Binary Tree Level Order Traversal II.py"}]}],"sources":["solutions"]},"topic-binarytreelongestconsecutivesequenceii":{"key":"topic-binarytreelongestconsecutivesequenceii","number":null,"title":"Binary Tree Longest Consecutive Sequence II","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Binary Tree Longest Consecutive Sequence II.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def longestConsecutive(self, root: TreeNode) -> int:\n        maxVal = 0\n        def longestPath(root):\n            nonlocal maxVal\n            if not root:\n                return [0, 0]\n            inr = dcr = 1\n            if root.left:\n                left = longestPath(root.left)\n                if root.val == root.left.val + 1:\n                    dcr = left[1] + 1\n                elif root.val == root.left.val - 1:\n                    inr = left[0] + 1\n            if root.right:\n                right = longestPath(root.right)\n                if root.val == root.right.val + 1:\n                    dcr = max(dcr, right[1] + 1)\n                elif root.val == root.right.val - 1:\n                    inr = max(inr, right[0] + 1)\n            maxVal = max(maxVal, dcr + inr - 1)\n            return [inr, dcr]\n        longestPath(root)\n        return maxVal","hash":"bc426abbab193a2d5495ef04135d43c42594f06b2ec779dd8f0669282a7f1281","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-07 Leetcoding Challenge/Binary Tree Longest Consecutive Sequence II.py"}]}],"sources":["solutions"]},"topic-binarytreepaths":{"key":"topic-binarytreepaths","number":null,"title":"Binary Tree Paths","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Binary Tree Paths.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def binaryTreePaths(self, root: TreeNode) -> List[str]:\n        if not root:\n            return []\n        result, stack = [], deque([(root, str(root.val))])\n        while stack:\n            node, path = stack.pop()\n            if node.left is None and node.right is None:\n                result.append(path)\n            if node.right:\n                stack.append((node.right, path + '->' + str(node.right.val)))\n            if node.left:\n                stack.append((node.left, path + '->' + str(node.left.val)))\n        return result","hash":"c42b17a6f53210b39682c93cecccf14edca2a45151c0320be4c421476886e003","origins":[{"source":"solutions","path":"Binary Tree Paths.py"}]}],"sources":["solutions"]},"topic-binarytreepostordertraversaliterative":{"key":"topic-binarytreepostordertraversaliterative","number":null,"title":"Binary Tree Postorder Traversal Iterative","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Binary Tree Postorder Traversal - Iterative.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def postorderTraversal(self, root: TreeNode) -> List[int]:\n        if root is None:\n            return []\n        stack, result, node = deque(), [], root\n        while stack or node:\n            while node:\n                if node.right:\n                    stack.append(node.right)\n                stack.append(node)\n                node = node.left\n            node = stack.pop()\n            if stack and stack[-1] == node.right:\n                stack[-1] = node\n                node = node.right\n            else:\n                result.append(node.val)\n                node = None\n        return result","hash":"569a526d17e1d90af9f016feaca330c27fb4d91369c978518d8b8a371a0a6bc9","origins":[{"source":"solutions","path":"Binary Tree/Binary Tree Postorder Traversal - Iterative.py"}]}],"sources":["solutions"]},"topic-binarytreepostordertraversalrecursive":{"key":"topic-binarytreepostordertraversalrecursive","number":null,"title":"Binary Tree Postorder Traversal Recursive","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Binary Tree Postorder Traversal - Recursive.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def postorderTraversal(self, root: TreeNode) -> List[int]:\n        return self.postorderTraversal(root.left) + self.postorderTraversal(root.right) + [root.val] if root else []","hash":"1360cd91a74bd7aa6aaeefc9cccf4369cea974057f6674cd5aa73dfb213e662b","origins":[{"source":"solutions","path":"Binary Tree/Binary Tree Postorder Traversal - Recursive.py"}]}],"sources":["solutions"]},"topic-binarytreepreordertraversal":{"key":"topic-binarytreepreordertraversal","number":null,"title":"Binary Tree Preorder Traversal","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Binary Tree Preorder Traversal.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def preorderTraversal(self, root: Optional[TreeNode]) -> List[int]:\n        result = []\n        def helper(node):\n            if node:\n                result.append(node.val)\n                helper(node.left)\n                helper(node.right)\n        helper(root)\n        return result","hash":"a960ceea284616a04f9ab37542f85ab72bb1a2bdc9af0dcc331e024e4aeecbe6","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-01 Leetcoding Challenge/Binary Tree Preorder Traversal.py"}]}],"sources":["solutions"]},"topic-binarytreepreordertraversaliterative":{"key":"topic-binarytreepreordertraversaliterative","number":null,"title":"Binary Tree Preorder Traversal Iterative","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Binary Tree Preorder Traversal - Iterative.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def preorderTraversal(self, root: TreeNode) -> List[int]:\n        if root is None:\n            return []\n        stack, result = deque([root,]), []\n        while stack:\n            node = stack.pop()\n            if node is not None:\n                result.append(node.val)\n                if node.right is not None:\n                    stack.append(node.right)\n                if node.left is not None:\n                    stack.append(node.left)\n        return result","hash":"8479143920778b016ef7f8149df6f69fc7f109b1c2c1a751ce9ebd589c7949fc","origins":[{"source":"solutions","path":"Binary Tree/Binary Tree Preorder Traversal - Iterative.py"}]}],"sources":["solutions"]},"topic-binarytreepreordertraversalmorristraversal":{"key":"topic-binarytreepreordertraversalmorristraversal","number":null,"title":"Binary Tree Preorder Traversal Morris Traversal","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Binary Tree Preorder Traversal - Morris Traversal.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def preorderTraversal(self, root: TreeNode) -> List[int]:\n        node, result = root, []\n        while node:\n            if node.left is None:\n                result.append(node.val)\n                node = node.right\n            else:\n                predecessor = node.left\n                while predecessor.right and predecessor.right is not node:\n                    predecessor = predecessor.right\n                if predecessor.right is None:\n                    result.append(node.val)\n                    predecessor.right = node\n                    node = node.left\n                else:\n                    predecessor.right = None\n                    node = node.right\n        return result","hash":"57a336e81572f0b3c95399db3eb305a25648fe712c83d5230f4502f44db80e87","origins":[{"source":"solutions","path":"Binary Tree/Binary Tree Preorder Traversal - Morris Traversal.py"}]}],"sources":["solutions"]},"topic-binarytreepreordertraversalrecursive":{"key":"topic-binarytreepreordertraversalrecursive","number":null,"title":"Binary Tree Preorder Traversal Recursive","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Binary Tree Preorder Traversal - Recursive.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def preorderTraversal(self, root: TreeNode) -> List[int]:\n        return [root.val] + self.preorderTraversal(root.left) + self.preorderTraversal(root.right) if root else []","hash":"3c31d21e94619c70eda2924f7ebdb7f3d28839006b315ce9a08166856f102315","origins":[{"source":"solutions","path":"Binary Tree/Binary Tree Preorder Traversal - Recursive.py"}]}],"sources":["solutions"]},"topic-binarytreetilt":{"key":"topic-binarytreetilt","number":null,"title":"Binary Tree Tilt","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Binary Tree Tilt.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def findTilt(self, root: TreeNode) -> int:\n        result = 0\n        \n        def getSum(node):\n            nonlocal result\n            if node is None:\n                return 0\n            leftSum = getSum(node.left)\n            rightSum = getSum(node.right)\n            result += abs(rightSum - leftSum)\n            return leftSum + rightSum + node.val\n        \n        getSum(root)\n        return result","hash":"3aee0a03fd9c4ccb16abb8980d01df9dc17b6be67c4e99c38b950d1b265a911a","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-11 Leetcoding Challenge/Binary Tree Tilt.py"}]}],"sources":["solutions"]},"topic-binarywatch":{"key":"topic-binarywatch","number":null,"title":"Binary Watch","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Binary Watch.py","code":"class Solution:\n    def readBinaryWatch(self, num: int) -> List[str]:\n        return ['%d:%02d' % (h, m) for h in range(12) for m in range(60) if (bin(h) + bin(m)).count('1') == num]","hash":"a6b41bfac3ad45cdf0c1b5927c9c0ab0285e22b8f35351fa2592542233918c5d","origins":[{"source":"solutions","path":"Binary Watch.py"}]}],"sources":["solutions"]},"topic-bitwiseandofnumbersrange":{"key":"topic-bitwiseandofnumbersrange","number":null,"title":"Bitwise AND of Numbers Range","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Bitwise AND of Numbers Range.py","code":"class Solution:\n    def rangeBitwiseAnd(self, left: int, right: int) -> int:\n        n = right\n        while n > left:\n            n &= (n - 1)\n        return left & n","hash":"dd5b83b4b1b754a6f8a10b441d14ee846fcf1483193e7b09008ae20e79ae1cc0","origins":[{"source":"solutions","path":"Bitwise AND of Numbers Range.py"}]}],"sources":["solutions"]},"topic-boatstosavepeople":{"key":"topic-boatstosavepeople","number":null,"title":"Boats to Save People","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Boats to Save People.py","code":"class Solution:\n    def numRescueBoats(self, people: List[int], limit: int) -> int:\n        people.sort()\n        i, j, boats = 0, len(people) - 1, 0\n        while i <= j:\n            boats += 1\n            if people[i] + people[j] <= limit:\n                i += 1\n            j -= 1\n        return boats","hash":"d6157b2cf54515b0079f9ec67d38c63c803255e7e3f2ff33393392610a21c650","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-01 Leetcoding Challenge/Boats to Save People.py"},{"source":"solutions","path":"LeetCoding Challenges/2022/2022-03 Leetcoding Challenge/Boats to Save People.py"},{"source":"solutions","path":"LeetCoding Challenges/2023/2023-04 Leetcoding Challenge/Boats to Save People.py"}]}],"sources":["solutions"]},"topic-boundaryofbinarytree":{"key":"topic-boundaryofbinarytree","number":null,"title":"Boundary of Binary Tree","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Boundary of Binary Tree.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def boundaryOfBinaryTree(self, root: TreeNode) -> List[int]:\n        result, stack = [], []\n        if root is None:\n            return result\n        def isLeaf(node):\n            return node.left is None and node.right is None\n        def addLeaves(node):\n            if isLeaf(node):\n                result.append(node.val)\n            else:\n                if node.left is not None:\n                    addLeaves(node.left)\n                if node.right is not None:\n                    addLeaves(node.right)\n        if not isLeaf(root):\n            result.append(root.val)\n        currentNode = root.left\n        while currentNode:\n            if not isLeaf(currentNode):\n                result.append(currentNode.val)\n            if currentNode.left is not None:\n                currentNode = currentNode.left\n            else:\n                currentNode = currentNode.right\n        addLeaves(root)\n        currentNode = root.right\n        while currentNode:\n            if not isLeaf(currentNode):\n                stack.append(currentNode.val)\n            if currentNode.right is not None:\n                currentNode = currentNode.right\n            else:\n                currentNode = currentNode.left\n        result.extend(stack[::-1])\n        return result","hash":"05d8c9ad1e9132ba317cf6bdf4cd24f25f9baa87e455d26222ee3e8fef3413e2","origins":[{"source":"solutions","path":"Boundary of Binary Tree.py"}]}],"sources":["solutions"]},"topic-braceexpansion":{"key":"topic-braceexpansion","number":null,"title":"Brace Expansion","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Brace Expansion.py","code":"class Solution:\n    def expand(self, S: str) -> List[str]:\n        tokens = [s.split(',') for s in S.replace('{', '|').replace('}', '|').split('|') if s != '']\n        result = []\n        def helper(index, currentString):\n            if index == len(tokens):\n                result.append(currentString)\n                return\n            for token in tokens[index]:\n                helper(index + 1, currentString + token)\n        helper(0, '')\n        return sorted(result)","hash":"c244ef14f497a664f02f4318ebc609379062ada34ce4d26c3e48095201d5ca99","origins":[{"source":"solutions","path":"Brace Expansion.py"}]}],"sources":["solutions"]},"algorithm-breadth-first-search":{"key":"algorithm-breadth-first-search","number":null,"title":"breadth first search","difficulty":"Unknown","tags":["Algorithm Reference"],"documents":[],"sources":["algorithms"],"solutions":[{"language":"python","name":"breadth_first_search.py","code":"#!/usr/bin/python\n\n\"\"\"Author: OMKAR PATHAK\"\"\"\n\nfrom __future__ import annotations\n\nfrom queue import Queue\n\n\nclass Graph:\n    def __init__(self) -> None:\n        self.vertices: dict[int, list[int]] = {}\n\n    def print_graph(self) -> None:\n        \"\"\"\n        prints adjacency list representation of graaph\n        >>> g = Graph()\n        >>> g.print_graph()\n        >>> g.add_edge(0, 1)\n        >>> g.print_graph()\n        0  :  1\n        \"\"\"\n        for i in self.vertices:\n            print(i, \" : \", \" -> \".join([str(j) for j in self.vertices[i]]))\n\n    def add_edge(self, from_vertex: int, to_vertex: int) -> None:\n        \"\"\"\n        adding the edge between two vertices\n        >>> g = Graph()\n        >>> g.print_graph()\n        >>> g.add_edge(0, 1)\n        >>> g.print_graph()\n        0  :  1\n        \"\"\"\n        if from_vertex in self.vertices:\n            self.vertices[from_vertex].append(to_vertex)\n        else:\n            self.vertices[from_vertex] = [to_vertex]\n\n    def bfs(self, start_vertex: int) -> set[int]:\n        \"\"\"\n        >>> g = Graph()\n        >>> g.add_edge(0, 1)\n        >>> g.add_edge(0, 1)\n        >>> g.add_edge(0, 2)\n        >>> g.add_edge(1, 2)\n        >>> g.add_edge(2, 0)\n        >>> g.add_edge(2, 3)\n        >>> g.add_edge(3, 3)\n        >>> sorted(g.bfs(2))\n        [0, 1, 2, 3]\n        \"\"\"\n        # initialize set for storing already visited vertices\n        visited = set()\n\n        # create a first in first out queue to store all the vertices for BFS\n        queue: Queue = Queue()\n\n        # mark the source node as visited and enqueue it\n        visited.add(start_vertex)\n        queue.put(start_vertex)\n\n        while not queue.empty():\n            vertex = queue.get()\n\n            # loop through all adjacent vertex and enqueue it if not yet visited\n            for adjacent_vertex in self.vertices[vertex]:\n                if adjacent_vertex not in visited:\n                    queue.put(adjacent_vertex)\n                    visited.add(adjacent_vertex)\n        return visited\n\n\nif __name__ == \"__main__\":\n    from doctest import testmod\n\n    testmod(verbose=True)\n\n    g = Graph()\n    g.add_edge(0, 1)\n    g.add_edge(0, 2)\n    g.add_edge(1, 2)\n    g.add_edge(2, 0)\n    g.add_edge(2, 3)\n    g.add_edge(3, 3)\n\n    g.print_graph()\n    # 0  :  1 -> 2\n    # 1  :  2\n    # 2  :  0 -> 3\n    # 3  :  3\n\n    assert sorted(g.bfs(2)) == [0, 1, 2, 3]\n","hash":"3f843a3fa9bec1389767e654f1135af393046e6fed8da40baf165dec8e583e14","origins":[{"source":"algorithms","path":"graphs/breadth_first_search.py","url":"https://github.com/TheAlgorithms/Python/blob/25c712f2692449e91a57748d328ef34fccf25654/graphs/breadth_first_search.py","commit":"25c712f2692449e91a57748d328ef34fccf25654"}]}]},"topic-brokencalculator":{"key":"topic-brokencalculator","number":null,"title":"Broken Calculator","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Broken Calculator.py","code":"class Solution:\n    def brokenCalc(self, X: int, Y: int) -> int:\n        result = 0\n        while Y > X:\n            result += 1\n            if Y % 2:\n                Y += 1\n            else:\n                Y //= 2\n        return result + X - Y","hash":"c1c50723b9e4c280cb514ea373ffdc7c67928349176410458a95879b2a94d111","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-02 Leetcoding Challenge/Broken Calculator.py"},{"source":"solutions","path":"LeetCoding Challenges/2022/2022-03 Leetcoding Challenge/Broken Calculator.py"}]}],"sources":["solutions"]},"topic-buildarrayfrompermutation":{"key":"topic-buildarrayfrompermutation","number":null,"title":"Build Array from Permutation","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Build Array from Permutation.py","code":"class Solution:\n    def buildArray(self, nums: List[int]) -> List[int]:\n        result = []\n        for i in range(len(nums)):\n            result.append(nums[nums[i]])\n        return result","hash":"d1789bf5bc3f1a2d389c71e425094ad8df1ea7193371eebe014667bf837ca2da","origins":[{"source":"solutions","path":"Build Array from Permutation.py"}]}],"sources":["solutions"]},"topic-buildingh2o":{"key":"topic-buildingh2o","number":null,"title":"Building H2O","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Building H2O.py","code":"from threading import Lock\n\nclass H2O:\n    def __init__(self):\n        self.executeHydrogen = Lock()\n        self.executeOxygen = Lock()\n        self.executeOxygen.acquire()\n        self.hydrogenCount = 0\n\n    def hydrogen(self, releaseHydrogen: 'Callable[[], None]') -> None:\n        self.executeHydrogen.acquire()\n        self.hydrogenCount += 1\n        # releaseHydrogen() outputs \"H\". Do not change or remove this line.\n        releaseHydrogen()\n        if self.hydrogenCount == 2:\n            self.hydrogenCount = 0\n            self.executeOxygen.release()\n        else:\n            self.executeHydrogen.release()\n        \n    def oxygen(self, releaseOxygen: 'Callable[[], None]') -> None:\n        self.executeOxygen.acquire()\n        # releaseOxygen() outputs \"O\". Do not change or remove this line.\n        releaseOxygen()\n        self.executeHydrogen.release()","hash":"995679a801fc6cc32ce4ba9278caa3f1f2e091c1bd0a66a58633f10808af7e77","origins":[{"source":"solutions","path":"Building H2O.py"}]}],"sources":["solutions"]},"topic-bulbswitcherii":{"key":"topic-bulbswitcherii","number":null,"title":"Bulb Switcher II","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Bulb Switcher II.py","code":"class Solution:\n    def flipLights(self, n: int, m: int) -> int:\n        n = min(n, 3)\n        if m == 0:\n            return 1\n        elif m == 1:\n            return [2, 3, 4][n - 1]\n        elif m == 2:\n            return [2, 4, 7][n - 1]\n        else:\n            return [2, 4, 8][n - 1]","hash":"0b8ad6a4fd29cbe010d01ba21714cd80bdd8005c509c8830700e11f61ad15563","origins":[{"source":"solutions","path":"Bulb Switcher II.py"}]}],"sources":["solutions"]},"topic-bulbswitcheriii":{"key":"topic-bulbswitcheriii","number":null,"title":"Bulb Switcher III","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Bulb Switcher III.py","code":"class Solution:\n    def numTimesAllBlue(self, lights: List[int]) -> int:\n        result, maxLightOn = 0, 0\n        for moment, light in enumerate(lights, 1):\n            maxLightOn = max(maxLightOn, light)\n            if maxLightOn == moment:\n                result += 1\n        return result","hash":"bc3b149aa0953413880238216c9e3dd032e0d32f1f7f7e0ead9efda0bfb6c748","origins":[{"source":"solutions","path":"Bulb Switcher III.py"}]}],"sources":["solutions"]},"topic-bulbswitcheriv":{"key":"topic-bulbswitcheriv","number":null,"title":"Bulb Switcher IV","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Bulb Switcher IV.py","code":"class Solution:\n    def minFlips(self, target: str) -> int:\n        return len([i[0] for i in groupby('0' + target)]) - 1","hash":"e153239ddb2e6a10df3f5c051ab816c47bec369f76788009b2b81cdf5b41f9a0","origins":[{"source":"solutions","path":"Bulb Switcher IV.py"}]}],"sources":["solutions"]},"topic-bullsandcows":{"key":"topic-bullsandcows","number":null,"title":"Bulls and Cows","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Bulls and Cows.py","code":"class Solution:\n    def getHint(self, secret: str, guess: str) -> str:\n        frequencyMap = defaultdict(int)\n        bulls = cows = 0\n        for index, s in enumerate(secret):\n            g = guess[index]\n            if s == g:\n                bulls += 1\n            else:\n                cows += int(frequencyMap[s] < 0) + int(frequencyMap[g] > 0)\n                frequencyMap[s] += 1\n                frequencyMap[g] -= 1\n        return '{}A{}B'.format(bulls, cows)","hash":"9f02559ebb2afc9e1e312622699322b8a577c6dd795c6bde8041bd96707e4cc9","origins":[{"source":"solutions","path":"Google Interview Questions/Bulls and Cows.py"},{"source":"solutions","path":"LeetCoding Challenges/2020/2020-09 Leetcoding Challenge/Bulls and Cows.py"}]}],"sources":["solutions"]},"topic-calculatorwithmethodchaining":{"key":"topic-calculatorwithmethodchaining","number":null,"title":"Calculator with Method Chaining","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"javascript","name":"Calculator with Method Chaining.js","code":"class Calculator {\n  \n    /** \n    * @param {number} value\n    */\n    constructor(value) {\n        this.value = value;\n        return this;\n    }\n\n    /** \n    * @param {number} value\n    * @return {Calculator}\n    */\n    add(value){\n        this.value += value;\n        return this;\n    }\n\n    /** \n    * @param {number} value\n    * @return {Calculator}\n    */\n    subtract(value){\n        this.value -= value;\n        return this;\n    }\n\n    /** \n    * @param {number} value\n    * @return {Calculator}\n    */  \n    multiply(value) {\n        this.value *= value;\n        return this;\n    }\n\n    /** \n    * @param {number} value\n    * @return {Calculator}\n    */\n    divide(value) {\n        if (value === 0) {\n            throw new Error('Division by zero is not allowed');\n        }\n        this.value /= value;\n        return this;\n    }\n\n    /** \n    * @param {number} value\n    * @return {Calculator}\n    */\n    power(value) {\n        this.value = Math.pow(this.value, value);\n        return this;\n    }\n\n    /** \n    * @return {number}\n    */\n    getResult() {\n        return this.value;\n    }\n}","hash":"42b41a1cfea94eb2b4adb3fa1b9e2355bd587e07e64dbab2ed9839bf1a24f768","origins":[{"source":"solutions","path":"Calculator with Method Chaining.js"}]}],"sources":["solutions"]},"topic-capacitytoshippackageswithinddays":{"key":"topic-capacitytoshippackageswithinddays","number":null,"title":"Capacity To Ship Packages Within D Days","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Capacity To Ship Packages Within D Days.py","code":"class Solution:\n    def shipWithinDays(self, weights: List[int], D: int) -> int:\n        def possible(capacity):\n            count, loaded = 1, 0\n            for w in weights:\n                if loaded + w <= capacity:\n                    loaded += w\n                else:\n                    count += 1\n                    loaded = w\n            return count <= D\n        maxWeight, low, high = max(weights), sum(weights) // D, max(weights) * len(weights) // D + 1\n        while low < high:\n            mid = low + ((high - low) >> 1)\n            if mid < maxWeight or not possible(mid):\n                low = mid + 1\n            else:\n                high = mid\n        return low","hash":"3bc7cd45544ee2a8461e40e178732642b835f7d49080da14a75b29176d817696","origins":[{"source":"solutions","path":"Capacity To Ship Packages Within D Days.py"}]},{"language":"python","name":"Capacity To Ship Packages Within D Days.py","code":"class Solution:\n    def shipWithinDays(self, weights: List[int], D: int) -> int:\n        def possible(capacity):\n            count, loaded = 1, 0\n            for w in weights:\n                if loaded + w <= capacity:\n                    loaded += w\n                else:\n                    count += 1\n                    loaded = w\n            return count <= D\n        maxWeight, low, high = max(weights), max(weights), sum(weights)\n        while low <= high:\n            mid = (high + low) >> 1\n            if mid < maxWeight or not possible(mid):\n                low = mid + 1\n            else:\n                high = mid - 1\n        return low","hash":"1174b9beeabb49a2ef0d354e530e251adea4c97ea7de1aaaf96d0c4a62f40aea","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-02 Leetcoding Challenge/Capacity To Ship Packages Within D Days.py"}]}],"sources":["solutions"]},"topic-capitalizethetitle":{"key":"topic-capitalizethetitle","number":null,"title":"Capitalize the Title","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Capitalize the Title.py","code":"class Solution:\n    def capitalizeTitle(self, title: str) -> str:\n        def capitalize(word: str) -> str:\n            if len(word) in [1, 2]:\n                return word.lower()\n            else:\n                return word[0].upper() + word[1:].lower()\n        return ' '.join([capitalize(word) for word in title.split()])","hash":"a4018f2a0323de44121a580556e4ec1af20ba4fab3fa9a0c803569163ec030a5","origins":[{"source":"solutions","path":"Capitalize the Title.py"}]}],"sources":["solutions"]},"topic-carpooling":{"key":"topic-carpooling","number":null,"title":"Car Pooling","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Car Pooling.py","code":"class Solution:\n    def carPooling(self, trips: List[List[int]], capacity: int) -> bool:\n        occupancyAtTimestamp = [0] * 1001\n        for trip in trips:\n            occupancyAtTimestamp[trip[1]] += trip[0]\n            occupancyAtTimestamp[trip[2]] -= trip[0]\n        usedCapacity = 0\n        for occupancyChange in occupancyAtTimestamp:\n            usedCapacity += occupancyChange\n            if usedCapacity > capacity:\n                return False\n        return True","hash":"a295cb28cb5a0794f7138d035a6301b942e53ae86c757e1158dfc8976c65b90e","origins":[{"source":"solutions","path":"Car Pooling.py"}]},{"language":"python","name":"Car Pooling.py","code":"class Solution:\n    def carPooling(self, trips: List[List[int]], capacity: int) -> bool:\n        tripOccupancy = [0] * 1002\n        for trip in trips:\n            tripOccupancy[trip[1]] += trip[0]\n            tripOccupancy[trip[2]] -= trip[0]\n        occupancy = 0\n        for occupancyDelta in tripOccupancy:\n            occupancy += occupancyDelta\n            if occupancy > capacity:\n                return False\n        return True","hash":"03607cebd744dd640ee04efd73c57389e75fd584782ab67a887d8c9521a46b86","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-09 Leetcoding Challenge/Car Pooling.py"}]}],"sources":["solutions"]},"topic-champagnetower":{"key":"topic-champagnetower","number":null,"title":"Champagne Tower","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Champagne Tower.py","code":"class Solution:\n    def champagneTower(self, poured: int, query_row: int, query_glass: int) -> float:\n        tower = [[0] * k for k in range(1, 102)]\n        tower[0][0] = poured\n        for row in range(query_row + 1):\n            for col in range(row + 1):\n                remaining = (tower[row][col] - 1.0) / 2.0\n                if remaining > 0:\n                    tower[row + 1][col] += remaining\n                    tower[row + 1][col + 1] += remaining\n        return min(1, tower[query_row][query_glass])","hash":"70d7ff305df46a2d0767e18dd29fd9db57fd9d5196ccd9af948772ae657c39a8","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-10 Leetcoding Challenge/Champagne Tower.py"},{"source":"solutions","path":"LeetCoding Challenges/2022/2022-03 Leetcoding Challenge/Champagne Tower.py"}]}],"sources":["solutions"]},"topic-cheapestflightswithinkstops":{"key":"topic-cheapestflightswithinkstops","number":null,"title":"Cheapest Flights Within K Stops","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Cheapest Flights Within K Stops.py","code":"class Solution:\n    def findCheapestPrice(self, n: int, flights: List[List[int]], src: int, dst: int, k: int) -> int:\n        dist = [float('inf')] * n\n        dist[src] = 0\n        for i in range(k + 1):\n            temp = dist[::]\n            for flight in flights:\n                if dist[flight[0]] != float('inf'):\n                    temp[flight[1]] = min(temp[flight[1]], dist[flight[0]] + flight[2])\n            dist = temp\n        return -1 if dist[dst] == float('inf') else dist[dst]","hash":"3fbe83de5cbb660cab636b8df10eb9ce161c109349c10a7fbda877f8fe74c7fe","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-01 Leetcoding Challenge/Cheapest Flights Within K Stops.py"}]}],"sources":["solutions"]},"topic-checkarrayformationthroughconcatenation":{"key":"topic-checkarrayformationthroughconcatenation","number":null,"title":"Check Array Formation Through Concatenation","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Check Array Formation Through Concatenation.py","code":"class Solution:\n    def canFormArray(self, arr: List[int], pieces: List[List[int]]) -> bool:\n        arrLength, hashMap, i = len(arr), {}, 0\n        for piece in pieces:\n            hashMap[piece[0]] = piece\n        while i < arrLength:\n            if arr[i] in hashMap:\n                j, piece = 0, hashMap[arr[i]]\n                while j < len(piece) and i < arrLength and piece[j] == arr[i]:\n                    j += 1\n                    i += 1\n                if j != len(piece):\n                    return False\n            else:\n                return False\n        return i == arrLength","hash":"7b716f193601089360341a385dc3fb19094ae8fe9096732f34ed22083335cc33","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-01 Leetcoding Challenge/Check Array Formation Through Concatenation.py"}]}],"sources":["solutions"]},"topic-checkcompletenessofabinarytree":{"key":"topic-checkcompletenessofabinarytree","number":null,"title":"Check Completeness of a Binary Tree","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Check Completeness of a Binary Tree.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def isCompleteTree(self, root: TreeNode) -> bool:\n        nodes, i = [(root, 1)], 0\n        while i < len(nodes):\n            node, v = nodes[i]\n            i += 1\n            if node:\n                nodes.append((node.left, v * 2))\n                nodes.append((node.right, v * 2 + 1))\n        return nodes[-1][1] == len(nodes)","hash":"b0fc1dd3099e65611cb8f4b1a555fbc7cb882e64b6bc1bb58a8f665ff5574f34","origins":[{"source":"solutions","path":"Check Completeness of a Binary Tree.py"},{"source":"solutions","path":"LeetCoding Challenges/2023/2023-03 Leetcoding Challenge/Check Completeness of a Binary Tree.py"}]}],"sources":["solutions"]},"topic-checkifastringcontainsallbinarycodesofsizek":{"key":"topic-checkifastringcontainsallbinarycodesofsizek","number":null,"title":"Check If a String Contains All Binary Codes of Size K","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Check If a String Contains All Binary Codes of Size K.py","code":"class Solution:\n    def hasAllCodes(self, s: str, k: int) -> bool:\n        return len({s[i - k : i] for i in range(k, len(s) + 1)}) == 1 << k","hash":"d77c49d5af4470c2dc972bfbb8f32a5cbb30bb776fc600aa6854d63b13d903fe","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-03 Leetcoding Challenge/Check If a String Contains All Binary Codes of Size K.py"},{"source":"solutions","path":"LeetCoding Challenges/2022/2022-05 Leetcoding Challenge/Check If a String Contains All Binary Codes of Size K.py"}]}],"sources":["solutions"]},"topic-checkifawordoccursasaprefixofanywordinasentence":{"key":"topic-checkifawordoccursasaprefixofanywordinasentence","number":null,"title":"Check If a Word Occurs As a Prefix of Any Word in a Sentence","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Check If a Word Occurs As a Prefix of Any Word in a Sentence.py","code":"class Solution:\n    def isPrefixOfWord(self, sentence: str, searchWord: str) -> int:\n        words = sentence.split()\n        for index, word in enumerate(words):\n            if word.startswith(searchWord):\n                return index + 1\n        return -1","hash":"7a65308cb171183ff667abddb6aaade2ef1f2b8138db0973442de037c3dd6367","origins":[{"source":"solutions","path":"Check If a Word Occurs As a Prefix of Any Word in a Sentence.py"}]}],"sources":["solutions"]},"topic-checkifall1sareatleastlengthkplacesaway":{"key":"topic-checkifall1sareatleastlengthkplacesaway","number":null,"title":"Check If All 1's Are at Least Length K Places Away","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Check If All 1's Are at Least Length K Places Away.py","code":"class Solution:\n    def kLengthApart(self, nums: List[int], k: int) -> bool:\n        prevOneIndex = float('-inf')\n        for i, num in enumerate(nums):\n            if num == 1:\n                if i - prevOneIndex - 1 < k:\n                    return False\n                prevOneIndex = i\n        return True","hash":"b578df525bcb177286e410400874b514a052d1586df032c3c09d8565f4a8e132","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-01 Leetcoding Challenge/Check If All 1's Are at Least Length K Places Away.py"}]}],"sources":["solutions"]},"topic-checkifallcharactershaveequalnumberofoccurrences":{"key":"topic-checkifallcharactershaveequalnumberofoccurrences","number":null,"title":"Check if All Characters Have Equal Number of Occurrences","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Check if All Characters Have Equal Number of Occurrences.py","code":"class Solution(object):\n    def areOccurrencesEqual(self, s):\n        \"\"\"\n        :type s: str\n        :rtype: bool\n        \"\"\"\n        freqMap = defaultdict(int)\n        val = 0\n        for char in s:\n            freqMap[char] += 1\n            val = freqMap[char]\n        for k, v in freqMap.items():\n            if v != val:\n                return False\n        return True","hash":"b9c656929a3ff9b354b2b68935f68d1a349703a162316211659d3639a3497e10","origins":[{"source":"solutions","path":"Check if All Characters Have Equal Number of Occurrences.py"}]}],"sources":["solutions"]},"topic-checkifeveryrowandcolumncontainsallnumbers":{"key":"topic-checkifeveryrowandcolumncontainsallnumbers","number":null,"title":"Check if Every Row and Column Contains All Numbers","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Check if Every Row and Column Contains All Numbers.py","code":"class Solution:\n    def checkValid(self, matrix: List[List[int]]) -> bool:\n        n = len(matrix)\n        colCheckMap = defaultdict(set)\n        for row in range(n):\n            rowSet = set()\n            for col in range(n):\n                rowSet.add(matrix[row][col])\n                colCheckMap[col].add(matrix[row][col])\n            if len(rowSet) != n:\n                return False\n        for _, s in colCheckMap.items():\n            if len(s) != n:\n                return False\n        return True","hash":"75cdaf27849ec8564d877cd9c42ca2234ecddccc8bb005e080b3f64760495a8c","origins":[{"source":"solutions","path":"Check if Every Row and Column Contains All Numbers.py"}]}],"sources":["solutions"]},"topic-checkifitisastraightline":{"key":"topic-checkifitisastraightline","number":null,"title":"Check If It Is a Straight Line","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Check If It Is a Straight Line.py","code":"class Solution:\n    def checkStraightLine(self, coordinates: List[List[int]]) -> bool:\n        if len(coordinates) in [0, 1, 2]:\n            return True\n        def getSlope(x, y):\n            if y[1] - x[1] == 0:\n                return 0\n            elif y[0] - x[0] == 0:\n                return float('inf')\n            else:\n                return ((y[1] - x[1]) / (y[0] - x[0]))\n        slope = getSlope(coordinates[0], coordinates[1])\n        for i in range(2, len(coordinates)):\n            if slope != getSlope(coordinates[i - 1], coordinates[i]):\n                return False\n        return True","hash":"a630d953f55f1b597ef8dae84df8013f90c000756c3e89dd7d9c57faa80f4391","origins":[{"source":"solutions","path":"Check If It Is a Straight Line.py"}]}],"sources":["solutions"]},"topic-checkifnanditsdoubleexist":{"key":"topic-checkifnanditsdoubleexist","number":null,"title":"Check If N and Its Double Exist","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Check If N and Its Double Exist.py","code":"class Solution:\n    def checkIfExist(self, arr: List[int]) -> bool:\n        hashSet = set()\n        for num in arr:\n            if (2 * num in hashSet) or (num % 2 == 0 and (num // 2) in hashSet):\n                return True\n            hashSet.add(num)\n        return False","hash":"7381a3778dc43ec1ec07c3e1f0ca2c55b20b7d27e29aee4a460d68f6f4da2796","origins":[{"source":"solutions","path":"Arrays/Check If N and Its Double Exist.py"}]}],"sources":["solutions"]},"topic-checkifnumbersareascendinginasentence":{"key":"topic-checkifnumbersareascendinginasentence","number":null,"title":"Check if Numbers Are Ascending in a Sentence","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Check if Numbers Are Ascending in a Sentence.py","code":"class Solution:\n    def areNumbersAscending(self, s: str) -> bool:\n        currentNumber = -1\n        for word in s.split():\n            if word.isnumeric():\n                if int(word) <= currentNumber:\n                    return False\n                else:\n                    currentNumber = int(word)\n        return True","hash":"919eb964ed3ecc006adeb204dd8a96eb7fd646f1505a64cf83bfd0aeff379ff2","origins":[{"source":"solutions","path":"Check if Numbers Are Ascending in a Sentence.py"}]}],"sources":["solutions"]},"topic-checkifobjectinstanceofclass":{"key":"topic-checkifobjectinstanceofclass","number":null,"title":"Check if Object Instance of Class","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"javascript","name":"Check if Object Instance of Class.js","code":"/**\n * @param {any} object\n * @param {any} classFunction\n * @return {boolean}\n */\nvar checkIfInstanceOf = function(obj, classFunction) {\n    const prototype = classFunction?.prototype;\n    while (obj !== null && obj !== undefined) {\n        obj = Object.getPrototypeOf(obj);\n        if (obj === prototype) return true;\n    }\n    return false;\n};\n\n/**\n * checkIfInstanceOf(new Date(), Date); // true\n */","hash":"2288579865b50ad3cdced327b7973ea7673e0986c802cae2f97dd555f4e9087d","origins":[{"source":"solutions","path":"Check if Object Instance of Class.js"}]}],"sources":["solutions"]},"topic-checkifonestringswapcanmakestringsequal":{"key":"topic-checkifonestringswapcanmakestringsequal","number":null,"title":"Check if One String Swap Can Make Strings Equal","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Check if One String Swap Can Make Strings Equal.py","code":"class Solution:\n    def areAlmostEqual(self, s1: str, s2: str) -> bool:\n        diffCharMap = defaultdict(list)\n        for i in range(len(s1)):\n            if s1[i] != s2[i]:\n                diffCharMap['s1'].append(s1[i])\n                diffCharMap['s2'].append(s2[i])\n        return len(diffCharMap['s1']) in [0, 2] and sorted(diffCharMap['s1']) == sorted(diffCharMap['s2'])","hash":"01021aea65b0d43c6db6d88719668d33349cb575cff3b968bf49b9c5ac9bf62f","origins":[{"source":"solutions","path":"Check if One String Swap Can Make Strings Equal.py"}]}],"sources":["solutions"]},"topic-checkifstringisaprefixofarray":{"key":"topic-checkifstringisaprefixofarray","number":null,"title":"Check If String Is a Prefix of Array","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Check If String Is a Prefix of Array.py","code":"class Solution:\n    def isPrefixString(self, s: str, words: List[str]) -> bool:\n        prefix = ''\n        for word in words:\n            prefix += word\n            if prefix == s:\n                return True\n            if len(prefix) > len(s):\n                return False\n        return False","hash":"a18d376cd0befe8e762a3bd328500c538ea082cdf4f0c7610b55d90ee709df9d","origins":[{"source":"solutions","path":"Check If String Is a Prefix of Array.py"}]}],"sources":["solutions"]},"topic-checkifstringistransformablewithsubstringsortoperations":{"key":"topic-checkifstringistransformablewithsubstringsortoperations","number":null,"title":"Check If String Is Transformable With Substring Sort Operations","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Check If String Is Transformable With Substring Sort Operations.py","code":"class Solution:\n    def isTransformable(self, s: str, t: str) -> bool:\n        positions = defaultdict(list)\n        for i in reversed(range(len(s))):\n            positions[int(s[i])].append(i)\n        for char in t:\n            num = int(char)\n            if not positions[num]:\n                return False\n            i = positions[num][-1]\n            for j in range(num):\n                if positions[j] and positions[j][-1] < i:\n                    return False\n            positions[num].pop()\n        return True","hash":"83f780d9391c5a1ac5d0aa6f7968dd0af0b56025b10f922f7472317c73774868","origins":[{"source":"solutions","path":"Weekly Contests/Weekly Contest 206/Check If String Is Transformable With Substring Sort Operations.py"}]}],"sources":["solutions"]},"topic-checkiftwoexpressiontreesareequivalent":{"key":"topic-checkiftwoexpressiontreesareequivalent","number":null,"title":"Check If Two Expression Trees are Equivalent","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Check If Two Expression Trees are Equivalent.py","code":"# Definition for a binary tree node.\n# class Node(object):\n#     def __init__(self, val=\" \", left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def checkEquivalence(self, root1: 'Node', root2: 'Node') -> bool:\n        tree1Count, tree2Count = defaultdict(int), defaultdict(int)\n        def bfsTraverse(root, frequencyCount):\n            queue = deque([root,])\n            while queue:\n                node = queue.popleft()\n                if node.left is None and node.right is None:\n                    frequencyCount[node.val] += 1\n                if node.left:\n                    queue.append(node.left)\n                if node.right:\n                    queue.append(node.right)\n        \n        bfsTraverse(root1, tree1Count)\n        bfsTraverse(root2, tree2Count)\n        return tree1Count == tree2Count","hash":"9396d3c9328e373344e96c9f584f89008c9199cf5fed14288c29d08d0217b7f4","origins":[{"source":"solutions","path":"Check If Two Expression Trees are Equivalent.py"}]}],"sources":["solutions"]},"topic-checkingexistenceofedgelengthlimitedpaths":{"key":"topic-checkingexistenceofedgelengthlimitedpaths","number":null,"title":"Checking Existence of Edge Length Limited Paths","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Checking Existence of Edge Length Limited Paths.py","code":"class UnionFind:\n    def __init__(self, size: int):\n        self.group = [i for i in range(size)]\n        self.rank = [0] * size\n    \n    def find(self, node: int) -> int:\n        if self.group[node] != node:\n            self.group[node] = self.find(self.group[node])\n        return self.group[node]\n    \n    def union(self, nodeA: int, nodeB: int):\n        groupA, groupB = self.find(nodeA), self.find(nodeB)\n        # node1 and node2 already belong to same group.\n        if groupA == groupB:\n            return\n        if self.rank[groupA] > self.rank[groupB]:\n            self.group[groupB] = groupA\n        elif self.rank[groupA] < self.rank[groupB]:\n            self.group[groupA] = groupB\n        else:\n            self.group[groupA] = groupB\n            self.rank[groupB] += 1\n    \n    def areConnected(self, nodeA: int, nodeB: int) -> bool:\n        return self.find(nodeA) == self.find(nodeB)\n\nclass Solution:\n    def distanceLimitedPathsExist(self, n: int, edgeList: List[List[int]], queries: List[List[int]]) -> List[bool]:\n        uf = UnionFind(n)\n        queriesCount = len(queries)\n        answer = [False] * queriesCount\n        # Store original indices with all queries.\n        queriesWithIndex = []\n        for i in range(queriesCount):\n            queriesWithIndex.append((queries[i][0], queries[i][1], queries[i][2], i))\n        # Sort all edges in increasing order of their edge weights.\n        edgeList.sort(key=lambda x: x[2])\n        # Sort all queries in increasing order of the limit of edge allowed.\n        queriesWithIndex.sort(key=lambda x: x[2])\n        edgeIndex = 0\n        # Iterate on each query one by one\n        for [p, q, limit, queryOriginalIndex] in queriesWithIndex:\n            # We can attach all edges which satisfy the limit given by the query.\n            while edgeIndex < len(edgeList) and edgeList[edgeIndex][2] < limit:\n                uf.union(edgeList[edgeIndex][0], edgeList[edgeIndex][1])\n                edgeIndex += 1\n            # If both nodes belong to the same component, it means we can reach them. \n            answer[queryOriginalIndex] = uf.areConnected(p, q)\n        return answer","hash":"5bc0abba22996071145c098e72812372a5265f81aa1480e7aa02bd34bc4db355","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-04 Leetcoding Challenge/Checking Existence of Edge Length Limited Paths.py"}]}],"sources":["solutions"]},"topic-cinemaseatallocation":{"key":"topic-cinemaseatallocation","number":null,"title":"Cinema Seat Allocation","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Cinema Seat Allocation.py","code":"class Solution:\n    def maxNumberOfFamilies(self, n: int, reservedSeats: List[List[int]]) -> int:\n        graph = defaultdict(set)\n        for row, col in reservedSeats:\n            graph[row].add(col)\n        result = 2 * n\n        for row, seats in graph.items():\n            familiesAllowed = 0\n            if 2 not in seats and 3 not in seats and 4 not in seats and 5 not in seats:\n                familiesAllowed += 1\n            if 6 not in seats and 7 not in seats and 8 not in seats and 9 not in seats:\n                familiesAllowed += 1\n            if 4 not in seats and 5 not in seats and 6 not in seats and 7 not in seats and familiesAllowed == 0:\n                familiesAllowed += 1\n            result += familiesAllowed - 2\n        return result","hash":"0aeac351b1a7cc3e260ad95c9c5bad0fe3fc32d69c44fdf211ced21b695d1ad7","origins":[{"source":"solutions","path":"Cinema Seat Allocation.py"}]}],"sources":["solutions"]},"topic-classesmorethan5students":{"key":"topic-classesmorethan5students","number":null,"title":"Classes More Than 5 Students","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"sql","name":"Classes More Than 5 Students.sql","code":"# Write your MySQL query statement below\nSELECT class\nFROM Courses\nGROUP BY class\nHAVING Count(*) >= 5;","hash":"095d6905a53854ef8306ebd43db4aa0faf3c0662f4a8364c66c04ed72baafb7d","origins":[{"source":"solutions","path":"Classes More Than 5 Students.sql"}]}],"sources":["solutions"]},"topic-clonegraph":{"key":"topic-clonegraph","number":null,"title":"Clone Graph","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Clone Graph.py","code":"\"\"\"\n# Definition for a Node.\nclass Node:\n    def __init__(self, val = 0, neighbors = None):\n        self.val = val\n        self.neighbors = neighbors if neighbors is not None else []\n\"\"\"\n\nclass Solution:\n    def __init__(self):\n        self.visited = {}\n    \n    def cloneGraph(self, node: 'Node') -> 'Node':\n        if not node:\n            return None\n        if node in self.visited:\n            return self.visited[node]\n        self.visited[node] = Node(node.val, [])\n        if node.neighbors:\n            self.visited[node].neighbors = [self.cloneGraph(n) for n in node.neighbors]\n        return self.visited[node]","hash":"eb5806ede9109b5bae74b763b1de9b05a27459e729ba2a4e562ffe782595c922","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-10 Leetcoding Challenge/Clone Graph.py"}]},{"language":"python","name":"Clone Graph.py","code":"\"\"\"\n# Definition for a Node.\nclass Node:\n    def __init__(self, val = 0, neighbors = None):\n        self.val = val\n        self.neighbors = neighbors if neighbors is not None else []\n\"\"\"\n\nclass Solution:\n    \n    def __init__(self):\n        self.visited = {}\n    \n    def cloneGraph(self, node: 'Node') -> 'Node':\n        if not node:\n            return None\n        if node in self.visited:\n            return self.visited[node]\n        self.visited[node] = Node(node.val, [])\n        if node.neighbors:\n            self.visited[node].neighbors = [self.cloneGraph(n) for n in node.neighbors]\n        return self.visited[node]","hash":"3de655a526bad3b363098b08b447ac6698284b1b7129757a5056f80078649413","origins":[{"source":"solutions","path":"LeetCoding Challenges/2022/2022-02 Leetcoding Challenge/Clone Graph.py"},{"source":"solutions","path":"LeetCoding Challenges/2023/2023-04 Leetcoding Challenge/Clone Graph.py"},{"source":"solutions","path":"Stacks and Queues/Clone Graph.py"}]}],"sources":["solutions"]},"topic-closestroom":{"key":"topic-closestroom","number":null,"title":"Closest Room","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Closest Room.py","code":"from sortedcontainers import SortedList\n\nclass Solution:\n    def closestRoom(self, rooms: List[List[int]], queries: List[List[int]]) -> List[int]:\n        sortedQueries = sorted([(size, preferredId, i) for i, (preferredId, size) in enumerate(queries)], reverse=True)\n        sortedRooms = sorted([(size, roomId) for roomId, size in rooms], reverse=True)\n        lenRooms, lenQueries, roomPointer, queryPointer, availableRooms, result = len(rooms), len(queries), 0, 0, SortedList(), [-1] * len(queries)\n        while roomPointer <= lenRooms and queryPointer < lenQueries:\n            if roomPointer < lenRooms and sortedRooms[roomPointer][0] >= sortedQueries[queryPointer][0]:\n                availableRooms.add(sortedRooms[roomPointer][1])\n                roomPointer += 1\n            else:\n                if len(availableRooms) != 0:\n                    preferredId, index = sortedQueries[queryPointer][1], sortedQueries[queryPointer][2]\n                    i = availableRooms.bisect(preferredId)\n                    candidates = []\n                    if i > 0:\n                        candidates.append(availableRooms[i - 1])\n                    if i < len(availableRooms):\n                        candidates.append(availableRooms[i])\n                    result[index] = min(candidates, key = lambda x : abs(x - preferredId))\n                queryPointer += 1\n        return result","hash":"b3aa944cabb405f7a1d3e343d3ed1e9f27bcc486ee2de21b27ce59549849f19f","origins":[{"source":"solutions","path":"Weekly Contests/Biweekly Contest 51/Closest Room.py"}]}],"sources":["solutions"]},"topic-coinchange":{"key":"topic-coinchange","number":null,"title":"Coin Change","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Coin Change.py","code":"class Solution:\n    def coinChange(self, coins: List[int], amount: int) -> int:\n        dp = [float('inf')] * (amount + 1)\n        dp[0] = 0\n        for coin in coins:\n            for i in range(coin, amount + 1):\n                dp[i] = min(dp[i], dp[i - coin] + 1)\n        return dp[amount] if dp[amount] != float('inf') else -1","hash":"2219c0085dbc136bd2a88ade80582fff0a6792e701e1e64210e8abbcfa305106","origins":[{"source":"solutions","path":"Google Interview Questions/Coin Change.py"},{"source":"solutions","path":"LeetCoding Challenges/2021/2021-03 Leetcoding Challenge/Coin Change.py"},{"source":"solutions","path":"LeetCoding Challenges/2022/2022-05 Leetcoding Challenge/Coin Change.py"}]}],"sources":["solutions"]},"topic-combinationsumiii":{"key":"topic-combinationsumiii","number":null,"title":"Combination Sum III","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Combination Sum III.py","code":"class Solution:\n    def combinationSum3(self, k: int, n: int) -> List[List[int]]:\n        result = []\n        \n        def backtrack(remaining, combination, start):\n            if remaining == 0 and len(combination) == k:\n                result.append(list(combination))\n                return\n            elif remaining < 0 or len(combination) == k:\n                return\n            for i in range(start, 10):\n                combination.append(i)\n                backtrack(remaining - i, combination, i + 1)\n                combination.pop()\n        \n        backtrack(n, [], 1)\n        return result","hash":"a0fc87d72b5d0e54955353d95a9d2922a1e08413f3d986b9b06e79bf5a5d607d","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-09 Leetcoding Challenge/Combination Sum III.py"},{"source":"solutions","path":"LeetCoding Challenges/2022/2022-05 Leetcoding Challenge/Combination Sum III.py"}]}],"sources":["solutions"]},"topic-combinationsbacktracking":{"key":"topic-combinationsbacktracking","number":null,"title":"Combinations Backtracking","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Combinations - Backtracking.py","code":"class Solution:\n    def combine(self, n: int, k: int) -> List[List[int]]:\n        result = []\n        def backtrack(startIndex, currentCombination):\n            if len(currentCombination) == k:\n                result.append(list(currentCombination))\n                return\n            for i in range(startIndex, n + 1):\n                currentCombination.append(i)\n                backtrack(i + 1, currentCombination)\n                currentCombination.pop()\n        backtrack(1, [])\n        return result","hash":"acb281eb9ac13ed31aaaa09eaf34d1bb8aefec68e7df2cd1ea853318d73bae1c","origins":[{"source":"solutions","path":"Combinations - Backtracking.py"}]}],"sources":["solutions"]},"topic-combinetwotables":{"key":"topic-combinetwotables","number":null,"title":"Combine Two Tables","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"sql","name":"Combine Two Tables.sql","code":"SELECT FirstName, LastName, City, State FROM Person LEFT JOIN Address ON Person.PersonId = Address.PersonId;","hash":"855208d196a626348b1c5da8a8c7a8b36a6fccf8afccf617d5ab268e81578208","origins":[{"source":"solutions","path":"Combine Two Tables.sql"}]}],"sources":["solutions"]},"topic-comparestringsbyfrequencyofthesmallestcharacter":{"key":"topic-comparestringsbyfrequencyofthesmallestcharacter","number":null,"title":"Compare Strings by Frequency of the Smallest Character","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Compare Strings by Frequency of the Smallest Character.py","code":"class Solution:\n    def numSmallerByFrequency(self, queries: List[str], words: List[str]) -> List[int]:\n        @lru_cache(maxsize=None)\n        def getCount(word):\n            charFrequencyMap = [0] * 26\n            for c in word:\n                charFrequencyMap[ord(c) - ord('a')] += 1\n            for i in range(26):\n                if charFrequencyMap[i] > 0:\n                    return charFrequencyMap[i]\n            return 0\n        wordValues, result, wordsCount = [getCount(word) for word in words], [], len(words)\n        wordValues.sort()\n        for query in queries:\n            val = getCount(query)\n            result.append(wordsCount - bisect.bisect(wordValues, val))\n        return result","hash":"5b27b5ea989335332f638e87f265fbf8e658eb5c94acd4fb6747514a5b01c073","origins":[{"source":"solutions","path":"Compare Strings by Frequency of the Smallest Character.py"}]}],"sources":["solutions"]},"topic-compareversionnumbers":{"key":"topic-compareversionnumbers","number":null,"title":"Compare Version Numbers","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Compare Version Numbers.py","code":"class Solution:\n    def compareVersion(self, version1: str, version2: str) -> int:\n        p1 = p2 = 0\n        n1, n2 = len(version1), len(version2)\n        \n        def getNextChunk(version, n, p):\n            if p >= n:\n                return 0, p\n            pEnd = p\n            while pEnd < n and version[pEnd] != '.':\n                pEnd += 1\n            num = int(version[p:pEnd]) if pEnd != n - 1 else int(version[p:n])\n            p = pEnd + 1\n            return num, p\n        \n        while p1 < n1 or p2 < n2:\n            num1, p1 = getNextChunk(version1, n1, p1)\n            num2, p2 = getNextChunk(version2, n2, p2)\n            if num1 != num2:\n                return 1 if num1 > num2 else -1\n        return 0","hash":"64a439a91f055685835509202c05a7b711a81ed37282417d0be6edb5bd88cc12","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-09 Leetcoding Challenge/Compare Version Numbers.py"},{"source":"solutions","path":"LeetCoding Challenges/2022/2022-02 Leetcoding Challenge/Compare Version Numbers.py"}]}],"sources":["solutions"]},"topic-complementofbase10integer":{"key":"topic-complementofbase10integer","number":null,"title":"Complement of Base 10 Integer","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Complement of Base 10 Integer.py","code":"class Solution:\n    def bitwiseComplement(self, N: int) -> int:\n        if N == 0:\n            return 1\n        n = floor(log2(N)) + 1\n        bitmask = (1 << n) - 1\n        return bitmask ^ N","hash":"5a3f6a81e1fb5245ae6b305b1b0a36faf0e008d7c11d6892b32e47296806345b","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-10 Leetcoding Challenge/Complement of Base 10 Integer.py"}]}],"sources":["solutions"]},"topic-complexnumbermultiplication":{"key":"topic-complexnumbermultiplication","number":null,"title":"Complex Number Multiplication","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Complex Number Multiplication.py","code":"class Solution:\n    def complexNumberMultiply(self, a: str, b: str) -> str:\n        aReal, aImg, bReal, bImg = int(a.split('+')[0]), int(a.split('+')[1][:-1]), int(b.split('+')[0]), int(b.split('+')[1][:-1])\n        return str((aReal * bReal) - (aImg * bImg)) + '+' + str((aReal * bImg) + (bReal * aImg)) + 'i'","hash":"0bff19e577238a5da3434e49e878bc9297632e1e97c60e364cc04a41704b0575","origins":[{"source":"solutions","path":"Complex Number Multiplication.py"},{"source":"solutions","path":"LeetCoding Challenges/2021/2021-08 LeetCoding Challenge/Complex Number Multiplication.py"}]}],"sources":["solutions"]},"topic-concatenatedwords":{"key":"topic-concatenatedwords","number":null,"title":"Concatenated Words","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Concatenated Words.py","code":"class Solution:\n    def findAllConcatenatedWordsInADict(self, words: List[str]) -> List[str]:\n        dictionary = set(words)\n        result = []\n        for word in words:\n            length = len(word)\n            dp = [False] * (length + 1)\n            dp[0] = True\n            for i in range(1, length + 1):\n                for j in range(1 if i == length else 0, i):\n                    if dp[i]:\n                        break\n                    dp[i] = dp[j] and (word[j:i] in dictionary)\n            if dp[length]:\n                result.append(word)\n        return result","hash":"4e7814979eebdef4267968ad24b6c9dd3d91e1ef4aaee4cd376e03c82d083917","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-01 Leetcoding Challenge/Concatenated Words.py"}]}],"sources":["solutions"]},"topic-confusingnumbers":{"key":"topic-confusingnumbers","number":null,"title":"Confusing Numbers","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Confusing Numbers.py","code":"class Solution:\n    def confusingNumber(self, N: int) -> bool:\n        SAME_UP_DOWN = ['0', '1', '8']\n        SAME_LEFT_RIGHT = ['6', '9']\n        s = str(N)\n        numLength = len(s)\n        if numLength == 1:\n            return s in SAME_LEFT_RIGHT\n        temp = []\n        for ch in s:\n            if ch in SAME_UP_DOWN:\n                temp.append(ch)\n            elif ch == '6':\n                temp.append('9')\n            elif ch == '9':\n                temp.append('6')\n            else:\n                return False\n        return ''.join(temp)[::-1] != s","hash":"35ecd1073ce3d75c70cad006e0ebb6998bef6f7ba3391b152f3d13d9164046e2","origins":[{"source":"solutions","path":"Mock Interviews/Google/Phone Interview 07/Confusing Numbers.py"}]}],"sources":["solutions"]},"topic-consecutivecharacters":{"key":"topic-consecutivecharacters","number":null,"title":"Consecutive Characters","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Consecutive Characters.py","code":"class Solution:\n    def maxPower(self, s: str) -> int:\n        power, maxPow = 1, 1\n        for i in range(1, len(s)):\n            if s[i - 1] == s[i]:\n                power += 1\n            else:\n                maxPow = max(maxPow, power)\n                power = 1\n        return max(maxPow, power)","hash":"356f64dddaaaf8d9f40f4c8f14ba485cf87983559f6fadd0155d0e067b0c7857","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-11 Leetcoding Challenge/Consecutive Characters.py"}]}],"sources":["solutions"]},"topic-constructbinarysearchtreefrompreordertraversal":{"key":"topic-constructbinarysearchtreefrompreordertraversal","number":null,"title":"Construct Binary Search Tree from Preorder Traversal","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Construct Binary Search Tree from Preorder Traversal.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def bstFromPreorder(self, preorder: List[int]) -> Optional[TreeNode]:\n        def constructBST(l: int, r: int) -> Optional[TreeNode]:\n            if l >= r:\n                return None\n            splitIndex = l + 1\n            while splitIndex < r and preorder[splitIndex] < preorder[l]:\n                splitIndex += 1\n            return TreeNode(preorder[l], constructBST(l + 1, splitIndex), constructBST(splitIndex, r))\n        return constructBST(0, len(preorder))","hash":"b6e7fb31271be93c263b223157bb3307321d9ee221a5a7c3f06eb856c40ea6dd","origins":[{"source":"solutions","path":"Construct Binary Search Tree from Preorder Traversal.py"}]}],"sources":["solutions"]},"topic-constructbinarytreefrompreorderandpostordertraversal":{"key":"topic-constructbinarytreefrompreorderandpostordertraversal","number":null,"title":"Construct Binary Tree from Preorder and Postorder Traversal","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Construct Binary Tree from Preorder and Postorder Traversal.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def constructFromPrePost(self, preorder: List[int], postorder: List[int]) -> Optional[TreeNode]:\n        n = len(preorder)\n        postorderIndexMap = {}\n        for index, val in enumerate(postorder):\n            postorderIndexMap[val] = index\n        preorderIndexMap = {}\n        for index, val in enumerate(preorder):\n            preorderIndexMap[val] = index\n\n        def constructTree(preStart: int, preEnd: int, postStart: int, postEnd: int) -> Optional[TreeNode]:\n            if preStart > preEnd or postStart > postEnd:\n                return None\n            leftStartValue = preorder[preStart + 1] if (preStart + 1) < n else None\n            rightStartValue = postorder[postEnd - 1] if (postEnd - 1) >= 0 else None\n            leftTreeNodeCount = max(preorderIndexMap[rightStartValue] - preStart - 1, 0) if rightStartValue else 0\n            rightTreeNodeCount = max(postorderIndexMap[leftStartValue] - postStart + 1, 0) if leftStartValue else 0\n            leftTree = constructTree(preStart + 1, preStart + leftTreeNodeCount, postStart, postStart + leftTreeNodeCount - 1)\n            rightTree = constructTree(preStart + leftTreeNodeCount + 1, preEnd, postStart + leftTreeNodeCount, postEnd - 1)\n            return TreeNode(preorder[preStart], leftTree, rightTree)\n        \n        return constructTree(0, n - 1, 0, n - 1)","hash":"24487a0e72bdbd91a4b8ed6c7d01247aa9301d93ffc48c94a1960160f11ae26e","origins":[{"source":"solutions","path":"Construct Binary Tree from Preorder and Postorder Traversal.py"}]}],"sources":["solutions"]},"topic-constructbinarytreefromstring":{"key":"topic-constructbinarytreefromstring","number":null,"title":"Construct Binary Tree from String","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Construct Binary Tree from String.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def str2tree(self, s: str) -> TreeNode:\n        def constructTree(currentIndex):\n            if currentIndex >= len(s):\n                return (currentIndex, None)\n            if s[currentIndex] == ')':\n                return (currentIndex + 1, None)\n            currentValue = []\n            while currentIndex < len(s) and s[currentIndex] not in ['(', ')']:\n                currentValue.append(s[currentIndex])\n                currentIndex += 1\n            node = TreeNode(int(''.join(currentValue)))\n            if currentIndex >= len(s) or s[currentIndex] == ')':\n                return (currentIndex + 1, node)\n            if currentIndex < len(s) and s[currentIndex] == '(':\n                currentIndex, node.left = constructTree(currentIndex + 1)\n            if currentIndex < len(s) and s[currentIndex] == '(':\n                currentIndex, node.right = constructTree(currentIndex + 1)\n            return (currentIndex + 1, node)\n        return constructTree(0)[1]","hash":"f1aa371aa56317992d1e0eabbe174665d65d15dda08e04b7021f4ffa9b921982","origins":[{"source":"solutions","path":"Construct Binary Tree from String.py"},{"source":"solutions","path":"LeetCoding Challenges/2021/2021-03 Leetcoding Challenge/Construct Binary Tree from String.py"}]}],"sources":["solutions"]},"topic-constructtherectangle":{"key":"topic-constructtherectangle","number":null,"title":"Construct the Rectangle","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Construct the Rectangle.py","code":"class Solution:\n    def constructRectangle(self, area: int) -> List[int]:\n        width = math.floor(math.sqrt(area))\n        while width:\n            if area % width == 0:\n                return [area // width, width]\n            else:\n                width -= 1","hash":"24e5ad95e7e4efe2a81cfce00f0e23547483b6d77c6abf7b9323441030f36a23","origins":[{"source":"solutions","path":"Construct the Rectangle.py"}]}],"sources":["solutions"]},"topic-containsduplicate":{"key":"topic-containsduplicate","number":null,"title":"Contains Duplicate","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Contains Duplicate.py","code":"class Solution:\n    def containsDuplicate(self, nums: List[int]) -> bool:\n        hashset = set()\n        for num in nums:\n            if num in hashset:\n                return True\n            hashset.add(num)\n        return False","hash":"ea595e0d36ed5f53bd18283f678dc996ddb71c1378198478ad1599813e48070e","origins":[{"source":"solutions","path":"Contains Duplicate.py"},{"source":"solutions","path":"Hash Table/Contains Duplicate.py"}]}],"sources":["solutions"]}});
